-- 5. End-to-end scenario tests using SET LOCAL to simulate users
-- Tests run inside a transaction, then roll back to keep data pristine.

BEGIN;

-- ── Seed test data ──────────────────────────────────────────────────────────
-- alice  (11111111) owns 'general' channel (aaaaaaaa)
-- bob    (22222222) is a moderator of 'general'
-- charlie(33333333) is a regular member / post author
-- diana  (44444444) has no relationship with 'general'

UPDATE public.channels
SET owner_id = '11111111-1111-1111-1111-111111111111'
WHERE id = 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa';

-- Bob is a moderator of 'general'
INSERT INTO public.channel_moderators (channel_id, user_id)
VALUES ('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', '22222222-2222-2222-2222-222222222222')
ON CONFLICT DO NOTHING;

-- Charlie wrote a post in 'general'
INSERT INTO public.posts (id, channel_id, author_id, title, content)
VALUES (
  'f0000000-0000-0000-0000-000000000001',
  'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
  '33333333-3333-3333-3333-333333333333',
  'Hello World',
  'First post!'
) ON CONFLICT DO NOTHING;

-- Diana wrote a comment on Charlie's post
INSERT INTO public.comments (id, post_id, author_id, content)
VALUES (
  'e0000000-0000-0000-0000-000000000001',
  'f0000000-0000-0000-0000-000000000001',
  '44444444-4444-4444-4444-444444444444',
  'Nice post!'
) ON CONFLICT DO NOTHING;

-- ── Test 1: Alice (owner) can see 'general' channel ─────────────────────────
SET LOCAL app.current_user_id = '11111111-1111-1111-1111-111111111111';
SELECT 'TEST 1 – Owner sees channel: '
  || CASE WHEN COUNT(*) > 0 THEN '✅ PASS' ELSE '❌ FAIL' END
FROM public.channels
WHERE id = 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa';

-- ── Test 2: Alice (owner) sees is_channel_owner() = true ────────────────────
SELECT 'TEST 2 – is_channel_owner() for alice: '
  || CASE WHEN public.is_channel_owner(
       'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
       '11111111-1111-1111-1111-111111111111'
     ) THEN '✅ PASS' ELSE '❌ FAIL' END;

-- ── Test 3: Bob (moderator) can_moderate_channel() = true ───────────────────
SELECT 'TEST 3 – can_moderate_channel() for bob: '
  || CASE WHEN public.can_moderate_channel(
       'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
       '22222222-2222-2222-2222-222222222222'
     ) THEN '✅ PASS' ELSE '❌ FAIL' END;

-- ── Test 4: Diana (no role) cannot moderate 'general' ───────────────────────
SELECT 'TEST 4 – diana cannot moderate general: '
  || CASE WHEN NOT public.can_moderate_channel(
       'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
       '44444444-4444-4444-4444-444444444444'
     ) THEN '✅ PASS' ELSE '❌ FAIL' END;

-- ── Test 5: Charlie (author) can see own post via SELECT policy ──────────────
SET LOCAL app.current_user_id = '33333333-3333-3333-3333-333333333333';
SELECT 'TEST 5 – charlie sees post in general (public channel): '
  || CASE WHEN COUNT(*) > 0 THEN '✅ PASS' ELSE '❌ FAIL' END
FROM public.posts
WHERE id = 'f0000000-0000-0000-0000-000000000001';

-- ── Test 6: Bob (moderator) can see Charlie's post ──────────────────────────
SET LOCAL app.current_user_id = '22222222-2222-2222-2222-222222222222';
SELECT 'TEST 6 – bob (moderator) sees charlie post: '
  || CASE WHEN COUNT(*) > 0 THEN '✅ PASS' ELSE '❌ FAIL' END
FROM public.posts
WHERE id = 'f0000000-0000-0000-0000-000000000001';

-- ── Test 7: Diana can see comments on accessible post ───────────────────────
SET LOCAL app.current_user_id = '44444444-4444-4444-4444-444444444444';
SELECT 'TEST 7 – diana sees comment on public post: '
  || CASE WHEN COUNT(*) > 0 THEN '✅ PASS' ELSE '❌ FAIL' END
FROM public.comments
WHERE id = 'e0000000-0000-0000-0000-000000000001';

-- ── Test 8: Alice (owner) adds a moderator ──────────────────────────────────
SET LOCAL app.current_user_id = '11111111-1111-1111-1111-111111111111';
INSERT INTO public.channel_moderators (channel_id, user_id)
VALUES ('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', '55555555-5555-5555-5555-555555555555')
ON CONFLICT DO NOTHING;
SELECT 'TEST 8 – alice inserts moderator (eve): '
  || CASE WHEN public.is_channel_moderator(
       'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
       '55555555-5555-5555-5555-555555555555'
     ) THEN '✅ PASS' ELSE '❌ FAIL' END;

-- ── Test 9: Moderator can update Charlie's post ─────────────────────────────
SET LOCAL app.current_user_id = '22222222-2222-2222-2222-222222222222';
UPDATE public.posts
SET content = '[Moderated by bob]'
WHERE id = 'f0000000-0000-0000-0000-000000000001';
SELECT 'TEST 9 – bob (moderator) edits charlie post: '
  || CASE WHEN content = '[Moderated by bob]' THEN '✅ PASS' ELSE '❌ FAIL' END
FROM public.posts
WHERE id = 'f0000000-0000-0000-0000-000000000001';

-- ── Test 10: Diana (no role) cannot update Charlie's post ───────────────────
SET LOCAL app.current_user_id = '44444444-4444-4444-4444-444444444444';
UPDATE public.posts
SET content = 'Hacked!'
WHERE id = 'f0000000-0000-0000-0000-000000000001';
SELECT 'TEST 10 – diana cannot edit charlie post: '
  || CASE WHEN content <> 'Hacked!' THEN '✅ PASS' ELSE '❌ FAIL' END
FROM public.posts
WHERE id = 'f0000000-0000-0000-0000-000000000001';

ROLLBACK;
"}

{"query": "
-- Run tests individually with full result set visibility
DO $$
DECLARE
  v_count   int;
  v_text    text;
  v_bool    boolean;
BEGIN
  -- Setup
  UPDATE public.channels SET owner_id = '11111111-1111-1111-1111-111111111111'
  WHERE id = 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa';

  INSERT INTO public.channel_moderators (channel_id, user_id)
  VALUES ('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','22222222-2222-2222-2222-222222222222')
  ON CONFLICT DO NOTHING;

  INSERT INTO public.posts (id, channel_id, author_id, title, content)
  VALUES ('f0000000-0000-0000-0000-000000000001',
          'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
          '33333333-3333-3333-3333-333333333333',
          'Hello World','First post!')
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO public.comments (id, post_id, author_id, content)
  VALUES ('e0000000-0000-0000-0000-000000000001',
          'f0000000-0000-0000-0000-000000000001',
          '44444444-4444-4444-4444-444444444444','Nice post!')
  ON CONFLICT (id) DO NOTHING;

  RAISE NOTICE '--- HELPER FUNCTION TESTS ---';

  -- T1: is_channel_owner – alice owns general
  SELECT public.is_channel_owner('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
                                 '11111111-1111-1111-1111-111111111111') INTO v_bool;
  RAISE NOTICE 'T1 is_channel_owner(alice, general)   = % → %',
    v_bool, CASE WHEN v_bool THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- T2: is_channel_owner – bob is NOT owner
  SELECT public.is_channel_owner('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
                                 '22222222-2222-2222-2222-222222222222') INTO v_bool;
  RAISE NOTICE 'T2 is_channel_owner(bob,   general)   = % → %',
    v_bool, CASE WHEN NOT v_bool THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- T3: is_channel_moderator – bob IS moderator
  SELECT public.is_channel_moderator('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
                                     '22222222-2222-2222-2222-222222222222') INTO v_bool;
  RAISE NOTICE 'T3 is_channel_moderator(bob, general) = % → %',
    v_bool, CASE WHEN v_bool THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- T4: is_channel_moderator – diana is NOT
  SELECT public.is_channel_moderator('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
                                     '44444444-4444-4444-4444-444444444444') INTO v_bool;
  RAISE NOTICE 'T4 is_channel_moderator(diana,general) = % → %',
    v_bool, CASE WHEN NOT v_bool THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- T5: can_moderate_channel – alice (owner) CAN moderate
  SELECT public.can_moderate_channel('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
                                     '11111111-1111-1111-1111-111111111111') INTO v_bool;
  RAISE NOTICE 'T5 can_moderate_channel(alice,general) = % → %',
    v_bool, CASE WHEN v_bool THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- T6: can_moderate_channel – bob (moderator) CAN moderate
  SELECT public.can_moderate_channel('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
                                     '22222222-2222-2222-2222-222222222222') INTO v_bool;
  RAISE NOTICE 'T6 can_moderate_channel(bob,  general) = % → %',
    v_bool, CASE WHEN v_bool THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- T7: can_moderate_channel – diana CANNOT moderate
  SELECT public.can_moderate_channel('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
                                     '44444444-4444-4444-4444-444444444444') INTO v_bool;
  RAISE NOTICE 'T7 can_moderate_channel(diana,general) = % → %',
    v_bool, CASE WHEN NOT v_bool THEN '✅ PASS' ELSE '❌ FAIL' END;

  RAISE NOTICE '';
  RAISE NOTICE '--- RLS SESSION CONTEXT TESTS ---';

  -- T8: get_current_user_id when set
  PERFORM set_config('app.current_user_id','11111111-1111-1111-1111-111111111111',true);
  SELECT public.get_current_user_id()::text INTO v_text;
  RAISE NOTICE 'T8 get_current_user_id() = % → %',
    v_text,
    CASE WHEN v_text = '11111111-1111-1111-1111-111111111111'
         THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- T9: Alice (owner) can see the channel
  PERFORM set_config('app.current_user_id','11111111-1111-1111-1111-111111111111',true);
  SELECT COUNT(*) INTO v_count FROM public.channels
  WHERE id = 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa';
  RAISE NOTICE 'T9 Alice SELECT channel  count=% → %',
    v_count, CASE WHEN v_count > 0 THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- T10: Charlie can see their post (public channel)
  PERFORM set_config('app.current_user_id','33333333-3333-3333-3333-333333333333',true);
  SELECT COUNT(*) INTO v_count FROM public.posts
  WHERE id = 'f0000000-0000-0000-0000-000000000001';
  RAISE NOTICE 'T10 Charlie SELECT post  count=% → %',
    v_count, CASE WHEN v_count > 0 THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- T11: Diana can see comment on public post
  PERFORM set_config('app.current_user_id','44444444-4444-4444-4444-444444444444',true);
  SELECT COUNT(*) INTO v_count FROM public.comments
  WHERE id = 'e0000000-0000-0000-0000-000000000001';
  RAISE NOTICE 'T11 Diana  SELECT comment count=% → %',
    v_count, CASE WHEN v_count > 0 THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- T12: Bob (moderator) can edit Charlie's post
  PERFORM set_config('app.current_user_id','22222222-2222-2222-2222-222222222222',true);
  UPDATE public.posts SET content = '[Moderated by bob]'
  WHERE id = 'f0000000-0000-0000-0000-000000000001';
  SELECT content INTO v_text FROM public.posts
  WHERE id = 'f0000000-0000-0000-0000-000000000001';
  RAISE NOTICE 'T12 Bob moderates post   content="%..." → %',
    LEFT(v_text,20),
    CASE WHEN v_text = '[Moderated by bob]' THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- T13: Diana (no role) cannot edit the post (RLS blocks silently)
  PERFORM set_config('app.current_user_id','44444444-4444-4444-4444-444444444444',true);
  UPDATE public.posts SET content = 'Hacked!'
  WHERE id = 'f0000000-0000-0000-0000-000000000001';
  SELECT content INTO v_text FROM public.posts
  WHERE id = 'f0000000-0000-0000-0000-000000000001';
  RAISE NOTICE 'T13 Diana cannot hack post content="%..." → %',
    LEFT(v_text,20),
    CASE WHEN v_text <> 'Hacked!' THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- T14: Alice (owner) can delete moderator record
  PERFORM set_config('app.current_user_id','11111111-1111-1111-1111-111111111111',true);
  INSERT INTO public.channel_moderators (channel_id, user_id)
  VALUES ('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','55555555-5555-5555-5555-555555555555')
  ON CONFLICT DO NOTHING;
  DELETE FROM public.channel_moderators
  WHERE channel_id = 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'
    AND user_id    = '55555555-5555-5555-5555-555555555555';
  SELECT public.is_channel_moderator('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
                                     '55555555-5555-5555-5555-555555555555') INTO v_bool;
  RAISE NOTICE 'T14 Alice removes moderator(eve) gone=% → %',
    NOT v_bool, CASE WHEN NOT v_bool THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- T15: Moderator self-removal (bob resigns)
  PERFORM set_config('app.current_user_id','22222222-2222-2222-2222-222222222222',true);
  DELETE FROM public.channel_moderators
  WHERE channel_id = 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'
    AND user_id    = '22222222-2222-2222-2222-222222222222';
  SELECT public.is_channel_moderator('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
                                     '22222222-2222-2222-2222-222222222222') INTO v_bool;
  RAISE NOTICE 'T15 Bob self-removal     gone=% → %',
    NOT v_bool, CASE WHEN NOT v_bool THEN '✅ PASS' ELSE '❌ FAIL' END;

  RAISE NOTICE '';
  RAISE NOTICE '=== ALL TESTS COMPLETE ===';

  -- Restore bob as moderator (cleanup)
  INSERT INTO public.channel_moderators (channel_id, user_id)
  VALUES ('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','22222222-2222-2222-2222-222222222222')
  ON CONFLICT DO NOTHING;

END;
$$;
"}
